/* ---- Play page ---- */
.play-container { max-width: 1200px; margin: 0 auto; }

.setup-panel {
    max-width: 450px;
    margin: 2rem auto;
    padding: 2rem;
}
.form-group { margin-bottom: 1.2rem; }
.form-group label {
    display: block;
    font-size: 0.85rem;
    color: var(--text-secondary);
    margin-bottom: 0.4rem;
    font-weight: 500;
}
select, input[type="number"], input[type="text"] {
    width: 100%;
    padding: 0.6rem;
.review-games-list .game-item.active {
    background: rgba(200, 149, 108, 0.18);
    border-left: 3px solid var(--accent);
}

/* Live win-rate panel on the Play page (easy mode, opt-in). */
.play-winrate-panel {
    margin-top: 0.85rem;
    margin-bottom: 1rem;
    padding: 0.85rem;
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: var(--radius-sm);
    box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.25);
}

.play-winrate-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.play-winrate-chart-wrap {
    position: relative;
    height: 130px;
}

/* Recorded human games: the row body opens the game, the button deletes it. */
.recorded-group .game-item.review-list-item {
    flex-direction: row;
    align-items: center;
    gap: 0.5rem;
}

.recorded-item-body { flex: 1 1 auto; min-width: 0; }
.resign-verdict.is-good strong { color: var(--success); }

.resign-verdict.is-caution,
.resign-verdict.is-unproven {
    border-color: rgba(255, 167, 38, 0.35);
    background: rgba(255, 167, 38, 0.07);
}
.resign-verdict.is-caution .resign-verdict-dot,
.resign-verdict.is-unproven .resign-verdict-dot { background: var(--warning); }
.resign-verdict.is-caution strong,
.resign-verdict.is-unproven strong { color: var(--warning); }

.resign-verdict.is-bad {
    border-color: rgba(239, 83, 80, 0.4);
    background: rgba(239, 83, 80, 0.09);
}
.resign-verdict.is-bad .resign-verdict-dot { background: var(--danger); box-shadow: 0 0 8px var(--danger); }
.resign-verdict.is-bad strong { color: var(--danger); }

.resign-stats { margin-bottom: 0.9rem; }

