cat >> web/static/css/style.css <<'CSS'

/* ---------------------------------------------------------------------------
   Bot vs Bot (Play page)
   The live match reuses the human game's .game-area / .info-panel layout, so
   only the match-specific pieces are styled here.
--------------------------------------------------------------------------- */

.play-mode-tabs {
    display: flex;
    gap: 0.5rem;
    justify-content: center;
    margin: 1.5rem auto 0;
    max-width: 450px;
}

.play-mode-tab {
    flex: 1;
    padding: 0.65rem 1rem;
    font-size: 0.9rem;
    font-weight: 500;
    color: var(--text-secondary);
    background: var(--bg-glass);
    border: 1px solid var(--border-glass);
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: var(--transition);
}
.play-mode-tab:hover { color: var(--text-primary); border-color: rgba(255, 255, 255, 0.18); }
.play-mode-tab.active {
    color: var(--text-primary);
    background: rgba(200, 149, 108, 0.16);
    border-color: var(--accent);
}

#match-setup-panel { max-width: 620px; }

.match-intro {
    color: var(--text-muted);
    font-size: 0.85rem;
    line-height: 1.5;
    margin-bottom: 1.5rem;
}

.match-side-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.match-side-note { color: var(--text-muted); font-weight: 400; }

.match-meta {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    color: var(--text-muted);
    line-height: 1.4;
    min-height: 2.1em;
}

.match-warning {
    margin-bottom: 1.2rem;
    padding: 0.7rem 0.85rem;
    font-size: 0.8rem;
    line-height: 1.45;
    color: var(--warning);
    background: rgba(255, 167, 38, 0.08);
    border: 1px solid rgba(255, 167, 38, 0.3);
    border-radius: var(--radius-sm);
}

/* --- Live match scoreboard --- */
.match-scoreboard {
    margin: 0.75rem 0 1rem;
    padding: 0.7rem 0.75rem;
    background: rgba(0, 0, 0, 0.25);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: var(--radius-sm);
}

.match-player-row {
    display: grid;
    grid-template-columns: auto 1fr auto auto;
    align-items: center;
    gap: 0.5rem;
    padding: 0.35rem 0.4rem;
    border-radius: var(--radius-sm);
    border-left: 3px solid transparent;
    transition: var(--transition);
}
/* Whoever is to move — makes the board readable without following the stones. */
.match-player-row.to-move {
    background: rgba(200, 149, 108, 0.12);
    border-left-color: var(--accent);
}

.match-player-name {
    font-weight: 600;
    font-size: 0.9rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.match-player-elo { font-size: 0.75rem; color: var(--text-secondary); white-space: nowrap; }
.match-player-wins {
    font-size: 1.05rem;
    font-weight: 700;
    min-width: 1.5rem;
    text-align: right;
}
.match-elo-up { color: var(--success); font-weight: 600; }
.match-elo-down { color: var(--danger); font-weight: 600; }
.match-elo-fixed { color: var(--text-muted); }

.match-series-line {
    margin-top: 0.5rem;
    padding-top: 0.5rem;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.78rem;
    color: var(--text-muted);
    text-align: center;
}

.match-speed-group { margin-top: 0.9rem; margin-bottom: 0.4rem; }

/* --- Per-game results list --- */
.match-results-panel { margin-top: 1rem; }

.match-results-list {
    margin-top: 0.5rem;
    max-height: 170px;
    overflow-y: auto;
    font-size: 0.78rem;
}

.match-result-row {
    display: grid;
    grid-template-columns: 2rem 1fr auto auto;
    gap: 0.4rem;
    align-items: center;
    padding: 0.3rem 0.15rem;
    border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}
.match-result-row:last-child { border-bottom: none; }
.match-result-index { color: var(--text-muted); }
.match-result-winner { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.match-result-margin { color: var(--text-secondary); }
.match-result-moves { color: var(--text-muted); }
.match-results-empty { color: var(--text-muted); }

/* Review page: a bot-vs-bot series groups its games under the match name. */
.match-series-group > summary { padding-left: 0.5rem; }
.match-game-item .match-game-line { font-size: 0.8rem; color: var(--text-muted); }

@media (max-width: 768px) {
    .match-side-grid { grid-template-columns: 1fr; }
}
